#!/usr/bin/env python3
"""Deterministically generate/check the v27 synchronized full fallback.

The immutable v26.8 source is historical recovery evidence, NOT the current
fallback after v27 promotion. Modular policy inputs own the generated output.
"""
from __future__ import annotations
import argparse
import hashlib
import json
import os
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
MAP="v27/candidate/MODULE_MAP.json"
BANNER=(
    "APP FACTORY v27 — SYNCHRONIZED FULL FALLBACK (GENERATED; DO NOT EDIT)\n"
    "SOURCE: v27/candidate/MASTER_CORE_v27_CANDIDATE.txt + registered "
    "modules and policy updates\n"
    "Precedence: v27 Core and v27 policy updates override retained legacy "
    "v26.8 prose where directly inconsistent.\n"
    "Status: ACTIVE v27 only when CURRENT.yaml resolves version 27; "
    "generated full policy remains synchronized.\n"
    "FALLBACK_BASELINE_USED must be disclosed when the resolver selects this file.\n"
    "\n"
)

def hash_bytes(raw: bytes)->str:
    return hashlib.sha1(b"blob "+str(len(raw)).encode("ascii")+b"\0"+raw).hexdigest()

def checked_path(path: str)->Path:
    if not isinstance(path,str) or not path.startswith("v27/candidate/"):
        raise ValueError("Only v27 candidate inputs permitted: "+repr(path))
    p=(ROOT/path).resolve()
    if not p.is_relative_to(ROOT): raise ValueError("Unsafe path "+path)
    return p

def render(manifest: dict)->str:
    core=checked_path(manifest["core"]["path"]).read_text(encoding="utf-8")
    source=manifest["original"]
    prefix=source["prefix"]
    from validate_v27_candidate import split_sections
    sections={}
    for entry in manifest["modules"]:
        raw=checked_path(entry["path"]).read_text(encoding="utf-8")
        leading,parts=split_sections(raw)
        if leading: raise ValueError("Unexpected module preamble "+entry["path"])
        found=[p["id"] for p in parts]
        if found!=entry["section_ids"]: raise ValueError("Module sections changed "+entry["path"])
        for p in parts:
            if p["id"] in sections: raise ValueError("Duplicate section "+p["id"])
            sections[p["id"]]=p["content"]
    expected=[s["id"] for s in manifest["sections"]]
    if len(expected)!=len(set(expected)) or set(expected)!=set(sections):
        raise ValueError("Missing or duplicate legacy source sections")
    legacy=prefix+"".join(sections[sid] for sid in expected)
    updates=[]
    for update in manifest.get("policy_updates",[]):
        updates.append(
            "\n\n===== V27 POLICY UPDATE: "+update["id"]+" =====\n"+
            checked_path(update["path"]).read_text(encoding="utf-8")
        )
    route_catalog=("\n\n===== V27 TASK ROUTES (SYNCED CANDIDATE METADATA) =====\n"
                   +json.dumps(manifest.get("task_routes",[]),ensure_ascii=False,indent=2))
    return (BANNER+core.rstrip("\n")+"\n\n===== COMPLETE LEGACY SECTION COVERAGE =====\n"
            +legacy+"".join(updates).rstrip("\n")+route_catalog.rstrip("\n")+"\n")

def main()->None:
    ap=argparse.ArgumentParser(description=__doc__)
    act=ap.add_mutually_exclusive_group(required=True)
    act.add_argument("--write",action="store_true",help="regenerate full fallback and SHA pins")
    act.add_argument("--check",action="store_true",help="fail if fallback or pins are stale")
    args=ap.parse_args()
    manifest_path=ROOT/MAP
    manifest=json.loads(manifest_path.read_text(encoding="utf-8"))
    expected=render(manifest).encode("utf-8")
    fb=manifest.get("living_fallback",{})
    dest=checked_path(fb.get("path",""))
    sha=hash_bytes(expected)
    seals={"core":hash_bytes(checked_path(manifest["core"]["path"]).read_bytes())}
    for entry in [*manifest["modules"],*manifest.get("policy_updates",[])]:
        seals[entry["id"]]=hash_bytes(checked_path(entry["path"]).read_bytes())
    if args.write:
        dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_bytes(expected)
        manifest["living_fallback"]["git_blob_sha"]=sha
        manifest["integrity_blob_sha"]=seals
        manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
        print(f"V27 FULL FALLBACK GENERATED: {dest.relative_to(ROOT)} sha256={sha}")
        return
    if not dest.is_file(): raise SystemExit("V27 FALLBACK CHECK FAIL: missing generated fallback")
    if dest.read_bytes()!=expected:
        raise SystemExit("V27 FALLBACK CHECK FAIL: generated output drift; run --write")
    if fb.get("git_blob_sha")!=sha:
        raise SystemExit("V27 FALLBACK CHECK FAIL: manifest hash is stale; run --write")
    if manifest.get("integrity_blob_sha")!=seals:
        raise SystemExit("V27 FALLBACK CHECK FAIL: module/core seals drift; run --write")
    print("V27 FALLBACK CHECK: PASS — synchronized exact generated bytes and source seals")

if __name__=="__main__":
    main()
